\begin{definition}
\label{def:8.1}
[Simple functions]
Let \(\Omega\subseteq\mathbb{R}^n\) be a measurable set, and let \(f:\Omega\to\mathbb{R}\) be a measurable function. The function \(f\) is called a \emph{simple function} if there exist an integer \(N\ge 1\) and real numbers \(c_1,\dots,c_N\) such that
\[
\label{eq:8.u1}
\forall x\in\Omega\ \exists j\in\{1,\dots,N\}\text{ with } f(x)=c_j.
\]
Equivalently, \(f\) is a simple function if and only if the image \(f(\Omega)\) is a finite subset of \(\mathbb{R}\).
\end{definition}

\begin{definition}
\label{def:8.2}
[Characteristic function]
Let \(\Omega\subseteq\mathbb{R}^n\) be measurable and let \(E\subseteq\Omega\) be measurable. The \emph{characteristic function} of \(E\) (also called the indicator function) is the function \(\chi_E:\Omega\to\mathbb{R}\) defined by
\[
\label{eq:8.u2}
\chi_E(x):=\begin{cases}1,&x\in E,\\0,&x\notin E.\end{cases}
\]
\end{definition}

\begin{lemma}
\label{lem:8.1}
Let $\Omega$ be a measurable subset of $\mathbb{R}^n$. Let $f,g:\Omega\to\mathbb{R}$ be simple functions, i.e., there exist $m,k\in\mathbb{N}$, pairwise disjoint measurable sets $A_1,\dots,A_m\subseteq\Omega$ and $B_1,\dots,B_k\subseteq\Omega$, and scalars $\alpha_1,\dots,\alpha_m,\beta_1,\dots,\beta_k\in\mathbb{R}$ such that
\[
\label{eq:8.u3}
f=\sum_{i=1}^m \alpha_i\,\mathbf{1}_{A_i},\qquad g=\sum_{j=1}^k \beta_j\,\mathbf{1}_{B_j}.
\]
Then $f+g$ is a simple function. Moreover, for any scalar $c\in\mathbb{R}$, the function $cf$ is a simple function.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:8.1}
Write $f=\sum_{i=1}^m \alpha_i\mathbf{1}_{A_i}$ and $g=\sum_{j=1}^k \beta_j\mathbf{1}_{B_j}$ with $A_i,B_j$ measurable and pairwise disjoint within each family. For each pair $(i,j)$ define $C_{ij}=A_i\cap B_j$, which is measurable. Then the sets $\{C_{ij}:1\le i\le m,\ 1\le j\le k\}$ are pairwise disjoint, and for every $x\in\Omega$ there exist unique indices $i,j$ such that $x\in A_i$ and $x\in B_j$, hence $x\in C_{ij}$. Therefore,
\[
\label{eq:8.u4}
(f+g)(x)=\alpha_i+\beta_j \quad\text{for } x\in C_{ij},
\]
so
\[
\label{eq:8.u5}
f+g=\sum_{i=1}^m\sum_{j=1}^k (\alpha_i+\beta_j)\,\mathbf{1}_{C_{ij}},
\]
which is a simple function.

For the scalar multiple, if $c\in\mathbb{R}$ then for $x\in A_i$ one has $(cf)(x)=c\alpha_i$, hence
\[
\label{eq:8.u6}
cf=\sum_{i=1}^m (c\alpha_i)\,\mathbf{1}_{A_i},
\]
which is a simple function.
\end{proof}

