\begin{lemma}
\label{lem:8.2}
Let $\Omega$ be a measurable subset of $\mathbb{R}^n$, and let $f:\Omega\to\mathbb{R}$ be a simple function, i.e., $f$ takes only finitely many values. Then there exist $N\in\mathbb{N}$, real numbers $c_1,\dots,c_N$, and pairwise disjoint measurable sets $E_1,\dots,E_N\subseteq\Omega$ such that
\[
\label{eq:8.u7}
f=\sum_{i=1}^N c_i\chi_{E_i}\quad\text{on }\Omega.
\]
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:8.2}
Since $f$ is simple, its range $f(\Omega)$ is a finite subset of $\mathbb{R}$. Enumerate the distinct values of $f$ as $\{c_1,\dots,c_N\}$.

For each $i\in\{1,\dots,N\}$, define
\[
\label{eq:8.u8}
E_i:=\{x\in\Omega: f(x)=c_i\}=f^{-1}(\{c_i\}).
\]
Because $f$ is measurable and $\{c_i\}$ is a Borel (hence measurable) subset of $\mathbb{R}$, each $E_i$ is measurable in $\Omega$. If $i\neq j$ then $E_i\cap E_j=\varnothing$ since $f(x)$ cannot equal two distinct real numbers. Moreover, for every $x\in\Omega$, $f(x)$ equals exactly one of the values $c_i$, so $x\in\bigcup_{i=1}^N E_i$.

For any $x\in\Omega$, exactly one indicator $\chi_{E_i}(x)$ equals $1$, namely for the unique $i$ with $x\in E_i$, and all others equal $0$. Hence
\[
\label{eq:8.u9}
\sum_{i=1}^N c_i\chi_{E_i}(x)=c_i=f(x).
\]
Therefore $f=\sum_{i=1}^N c_i\chi_{E_i}$ on $\Omega$.
\end{proof}

