\begin{lemma}
\label{lem:8.3}
Let $\Omega\subseteq\mathbb{R}^n$ be measurable, and let $f:\Omega\to[0,+\infty]$ be measurable. Then there exists a sequence $(f_n)_{n\ge 1}$ of nonnegative simple functions $f_n:\Omega\to\mathbb{R}$ such that:
\begin{enumerate}
\item $0\le f_n\le f_{n+1}$ pointwise on $\Omega$ for all $n\ge 1$;
\item For every $x\in\Omega$, $\lim_{n\to\infty} f_n(x)=f(x)$.
\end{enumerate}
\end{lemma}

\begin{definition}
\label{def:8.3}
[Lebesgue integral of a non-negative simple function]
Let $\Omega\subseteq\mathbb{R}^n$ be a measurable set (with respect to Lebesgue measure $m$). A function $f:\Omega\to[0,\infty)$ is called a (non-negative) simple function if it is measurable and its range $f(\Omega)$ is a finite subset of $[0,\infty)$. For such a function $f$, the Lebesgue integral of $f$ over $\Omega$ is defined by
\[
\label{eq:8.u14}
\int_{\Omega} f\,dm \, := \, \sum_{\substack{\lambda\in f(\Omega)\\ \lambda>0}} \lambda\, m\bigl(\{x\in\Omega: f(x)=\lambda\}\bigr).
\]
\end{definition}

\begin{lemma}
\label{lem:8.4}
Let $\Omega\subseteq\mathbb{R}^n$ be measurable, let $E_1,\dots,E_N\subseteq\Omega$ be pairwise disjoint measurable sets, and let $c_1,\dots,c_N\ge 0$. Define the simple function $f=\sum_{j=1}^N c_j\chi_{E_j}$ on $\Omega$. Then
\[
\label{eq:8.u15}
\int_{\Omega} f\,dm = \sum_{j=1}^{N} c_j\, m(E_j).
\]
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:8.4}
Since the sets $E_1,\dots,E_N$ are pairwise disjoint, for every $x\in\Omega$ there is at most one index $j$ with $x\in E_j$. Hence
\[
\label{eq:8.u16}
f(x)=\sum_{j=1}^N c_j\chi_{E_j}(x)
\]
assumes the value $c_j$ on $E_j$ and the value $0$ on $\Omega\setminus \bigcup_{j=1}^N E_j$. Therefore $f$ is a nonnegative simple function with representation
\[
\label{eq:8.u17}
f=\sum_{j=1}^N c_j\chi_{E_j}+0\cdot\chi_{\Omega\setminus \cup_{j=1}^N E_j},
\]
where the sets in the sum are measurable and pairwise disjoint. By the definition of the Lebesgue integral of a nonnegative simple function,
\[
\label{eq:8.u18}
\int_{\Omega} f\,dm=\sum_{j=1}^N c_j\,m(E_j)+0\cdot m\Bigl(\Omega\setminus \bigcup_{j=1}^N E_j\Bigr)=\sum_{j=1}^N c_j\,m(E_j).
\]
\end{proof}

