\begin{proposition}
\label{prop:8.1.1}
Let $\Omega$ be a measurable set in $\mathbb{R}^n$ with Lebesgue measure $m$, and let $f,g:\Omega\to\mathbb{R}$ be non-negative simple functions. Write
\[
\label{eq:8.u19}
f=\sum_{k=1}^N a_k\,\chi_{A_k},\qquad g=\sum_{j=1}^M b_j\,\chi_{B_j},
\]
where $a_k,b_j\ge 0$ and $A_k,B_j\subset\Omega$ are measurable and pairwise disjoint within each family. Define
\[
\label{eq:8.u20}
\int_\Omega f\,dm:=\sum_{k=1}^N a_k\,m(A_k),\qquad \int_\Omega g\,dm:=\sum_{j=1}^M b_j\,m(B_j).
\]
Then, $0\le \int_\Omega f\,dm\le \infty$. Moreover, $\int_\Omega f\,dm=0$ if and only if $m(\{x\in\Omega: f(x)\ne 0\})=0$.

\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.1.1}
Since $a_k\ge 0$ and $m(A_k)\ge 0$, each term $a_k m(A_k)$ is non-negative, hence $\int_\Omega f\,dm=\sum_{k=1}^N a_k m(A_k)\ge 0$. The value lies in $[0,\infty]$ because each $m(A_k)\in[0,\infty]$.

If $\int_\Omega f\,dm=0$, then $\sum_{k=1}^N a_k m(A_k)=0$ with all summands $\ge 0$, so for every $k$ one has $a_k m(A_k)=0$. For those $k$ with $a_k>0$ this forces $m(A_k)=0$. The set where $f\ne 0$ equals $\bigcup_{k: a_k>0} A_k$, a finite union of measure-zero sets, hence has measure $0$.

Conversely, if $m(\{f\ne 0\})=0$, then $m\bigl(\bigcup_{k: a_k>0} A_k\bigr)=0$, so each $A_k$ with $a_k>0$ has measure $0$ (since $A_k\subset \{f\ne 0\}$). Therefore $\int_\Omega f\,dm=\sum_{k=1}^N a_k m(A_k)=0$.


\end{proof}

