\begin{proposition}
\label{prop:8.1.2}
Let $\Omega$ be a measurable set in $\mathbb{R}^n$ with Lebesgue measure $m$, and let $f,g:\Omega\to\mathbb{R}$ be non-negative simple functions. Write
\[
\label{eq:8.u19}
f=\sum_{k=1}^N a_k\,\chi_{A_k},\qquad g=\sum_{j=1}^M b_j\,\chi_{B_j},
\]
where $a_k,b_j\ge 0$ and $A_k,B_j\subset\Omega$ are measurable and pairwise disjoint within each family. Define
\[
\label{eq:8.u20}
\int_\Omega f\,dm:=\sum_{k=1}^N a_k\,m(A_k),\qquad \int_\Omega g\,dm:=\sum_{j=1}^M b_j\,m(B_j).
\]
Then,  $\int_\Omega (f+g)\,dm=\int_\Omega f\,dm+\int_\Omega g\,dm$.

\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.1.2}


Using the given representations, partition $\Omega$ into the measurable pairwise disjoint sets $C_{k,j}:=A_k\cap B_j$ ($1\le k\le N$, $1\le j\le M$) together with the leftover parts $A_k\setminus\bigcup_{j=1}^M B_j$ and $B_j\setminus\bigcup_{k=1}^N A_k$ (on which one of the functions is $0$). On each piece, $f+g$ is constant with value $a_k+b_j$ on $C_{k,j}$, value $a_k$ on $A_k\setminus\bigcup_j B_j$, and value $b_j$ on $B_j\setminus\bigcup_k A_k$. Hence
\[
\label{eq:8.u21}
\int_\Omega (f+g)\,dm=\sum_{k,j}(a_k+b_j)m(A_k\cap B_j)+\sum_k a_k\,m\Bigl(A_k\setminus\bigcup_j B_j\Bigr)+\sum_j b_j\,m\Bigl(B_j\setminus\bigcup_k A_k\Bigr).
\]
Using finite additivity of $m$ on disjoint unions,
\[
\label{eq:8.u22}
m(A_k)=\sum_j m(A_k\cap B_j)+m\Bigl(A_k\setminus\bigcup_j B_j\Bigr),\qquad
m(B_j)=\sum_k m(A_k\cap B_j)+m\Bigl(B_j\setminus\bigcup_k A_k\Bigr).
\]
Substituting gives
\[
\label{eq:8.u23}
\int_\Omega (f+g)\,dm=\sum_k a_k m(A_k)+\sum_j b_j m(B_j)=\int_\Omega f\,dm+\int_\Omega g\,dm.
\]


\end{proof}

