where $a_k,b_j\ge 0$ and $A_k,B_j\subset\Omega$ are measurable and pairwise disjoint within each family. Define
\[
\label{eq:8.u20}
\int_\Omega f\,dm:=\sum_{k=1}^N a_k\,m(A_k),\qquad \int_\Omega g\,dm:=\sum_{j=1}^M b_j\,m(B_j).
\]

For any $c>0$, $\int_\Omega (cf)\,dm=c\int_\Omega f\,dm$.

\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.1.3}
If $f=\sum_{k=1}^N a_k\chi_{A_k}$, then $cf=\sum_{k=1}^N (ca_k)\chi_{A_k}$, so
\[
\label{eq:8.u24}
\int_\Omega (cf)\,dm=\sum_{k=1}^N (ca_k)m(A_k)=c\sum_{k=1}^N a_k m(A_k)=c\int_\Omega f\,dm.
\]


\end{proof}

