\begin{proposition}
\label{prop:8.1.4}
Let $\Omega$ be a measurable set in $\mathbb{R}^n$ with Lebesgue measure $m$, and let $f,g:\Omega\to\mathbb{R}$ be non-negative simple functions. Write
\[
\label{eq:8.u19}
f=\sum_{k=1}^N a_k\,\chi_{A_k},\qquad g=\sum_{j=1}^M b_j\,\chi_{B_j},
\]
where $a_k,b_j\ge 0$ and $A_k,B_j\subset\Omega$ are measurable and pairwise disjoint within each family. Define
\[
\label{eq:8.u20}
\int_\Omega f\,dm:=\sum_{k=1}^N a_k\,m(A_k),\qquad \int_\Omega g\,dm:=\sum_{j=1}^M b_j\,m(B_j).
\]
 If $f(x)\le g(x)$ for all $x\in\Omega$, then $\int_\Omega f\,dm\le \int_\Omega g\,dm$.

\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.1.4}

Use the common refinement $C_{k,j}=A_k\cap B_j$ as in Proposition 8.1.2. On each $C_{k,j}$ one has $f=a_k$ and $g=b_j$, and the assumption $f\le g$ implies $a_k\le b_j$ whenever $m(C_{k,j})>0$. Therefore
\[
\label{eq:8.u25}
\int_\Omega f\,dm=\sum_{k,j} a_k\,m(C_{k,j})\le \sum_{k,j} b_j\,m(C_{k,j})=\int_\Omega g\,dm,
\]
where the equalities follow from finite additivity and the disjoint decomposition by the $C_{k,j}$ together with the pieces where one function is $0$.
\end{proof}

