\begin{definition}
\label{def:8.4}
[Almost everywhere]
Let $(\Omega,\Sigma,\mu)$ be a measure space and let $P(x)$ be a property defined for $x\in\Omega$. The property $P$ holds \emph{for almost every} $x\in\Omega$ if there exists a measurable set $N\subseteq\Omega$ with $\mu(N)=0$ such that $P(x)$ holds for all $x\in\Omega\setminus N$.
\end{definition}

\begin{proposition}
\label{prop:8.2}
Let $(\Omega,\Sigma,\mu)$ be a measure space and let $f:\Omega\to[0,\infty]$ be a measurable function. Then
\[
\label{eq:8.u26}
\int_{\Omega} f\,d\mu = 0 \quad\Longleftrightarrow\quad f(x)=0\ \text{for }\mu\text{-almost every }x\in\Omega.
\]
\end{proposition}

\begin{definition}
\label{def:8.5}
[Majorization]
Let $\Omega$ be a set and let $f,g:\Omega\to\mathbb{R}$ be functions. The function $f$ \emph{majorizes} $g$ (equivalently, $g$ \emph{minorizes} $f$) if
\[
\label{eq:8.u31}
\forall x\in\Omega,\quad f(x)\ge g(x).
\]
\end{definition}

\begin{definition}
\label{def:8.6}
[Lebesgue integral for non-negative functions]
Let \(\Omega\subseteq\mathbb{R}^n\) be a Lebesgue measurable set, and let \(f:\Omega\to[0,\infty]\) be a Lebesgue measurable function. A \emph{non-negative simple function} on \(\Omega\) is a function \(s:\Omega\to[0,\infty)\) of the form \(s=\sum_{k=1}^m a_k\mathbf{1}_{E_k}\), where \(m\in\mathbb{N}\), \(a_k\ge 0\), and each \(E_k\subseteq\Omega\) is Lebesgue measurable. For such \(s\), define
\[
\label{eq:8.u32}
\int_{\Omega} s\,dx:=\sum_{k=1}^m a_k\,|E_k|,
\]
where \(|E_k|\) denotes the Lebesgue measure of \(E_k\). The \emph{Lebesgue integral} of \(f\) over \(\Omega\) is defined by
\[
\label{eq:8.u33}
\int_{\Omega} f\,dx:=\sup\left\{\int_{\Omega} s\,dx : s\text{ is a non-negative simple function on }\Omega\text{ and }0\le s\le f\text{ pointwise on }\Omega\right\}.
\]
\end{definition}

\begin{proposition}
\label{prop:8.3.1}
Let $(X,\mathcal{A},\mu)$ be a measure space, let $\Omega\in\mathcal{A}$, and let $f,g:\Omega\to[0,\infty]$ be $\mathcal{A}$-measurable. Define the integral over $\Omega$ by $\int_\Omega f\,d\mu:=\int_X f\chi_\Omega\,d\mu$. One has $0\le \int_{\Omega} f\,d\mu\le \infty$. Moreover, $\int_{\Omega} f\,d\mu = 0$ if and only if $f(x)=0$ for $\mu$-almost every $x\in\Omega$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.3.1}
Extend $f$ and $g$ to $X$ by $\tilde f:=f\chi_\Omega$ and $\tilde g:=g\chi_\Omega$. Then $\tilde f,\tilde g:X\to[0,\infty]$ are measurable and $\int_\Omega f\,d\mu=\int_X \tilde f\,d\mu$, $\int_\Omega g\,d\mu=\int_X \tilde g\,d\mu$.

By definition of the Lebesgue integral for non-negative measurable functions, $\int_X \tilde f\,d\mu\in[0,\infty]$, hence $0\le\int_\Omega f\,d\mu\le\infty$. If $\tilde f=0$ $\mu$-a.e. on $X$, then clearly $\int_X\tilde f\,d\mu=0$. Conversely, assume $\int_X \tilde f\,d\mu=0$. For each $n\in\mathbb{N}$ set $A_n:=\{x\in X:\tilde f(x)\ge 1/n\}$. Then $\tilde f\ge (1/n)\chi_{A_n}$, so by monotonicity of the integral for non-negative functions,
\[
\label{eq:8.u34}
0=\int_X\tilde f\,d\mu\ge \frac1n\int_X\chi_{A_n}\,d\mu=\frac1n\mu(A_n),
\]
which implies $\mu(A_n)=0$ for all $n$. Since $\{\tilde f>0\}=\bigcup_{n=1}^\infty A_n$, it follows that $\mu(\{\tilde f>0\})=0$, i.e. $\tilde f=0$ $\mu$-a.e. on $X$, equivalently $f=0$ $\mu$-a.e. on $\Omega$.
\end{proof}

