\begin{proposition}
\label{prop:8.3.2}
Let $(X,\mathcal{A},\mu)$ be a measure space, let $\Omega\in\mathcal{A}$, and let $f,g:\Omega\to[0,\infty]$ be $\mathcal{A}$-measurable. Define the integral over $\Omega$ by $\int_\Omega f\,d\mu:=\int_X f\chi_\Omega\,d\mu$.
 For any $c>0$, $\int_{\Omega} cf\,d\mu = c \int_{\Omega} f\,d\mu$.

\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.3.2}
Extend $f$ and $g$ to $X$ by $\tilde f:=f\chi_\Omega$ and $\tilde g:=g\chi_\Omega$. Then $\tilde f,\tilde g:X\to[0,\infty]$ are measurable and $\int_\Omega f\,d\mu=\int_X \tilde f\,d\mu$, $\int_\Omega g\,d\mu=\int_X \tilde g\,d\mu$.


Let $c>0$. For any non-negative simple function $\varphi$ with $0\le \varphi\le \tilde f$, the function $c\varphi$ is simple and satisfies $0\le c\varphi\le c\tilde f$. Hence
\[
\label{eq:8.u35}
\sup_{0\le\varphi\le \tilde f}\int_X c\varphi\,d\mu \le \int_X c\tilde f\,d\mu.
\]
Conversely, any simple $\psi$ with $0\le\psi\le c\tilde f$ yields $\varphi:=\psi/c$ simple with $0\le\varphi\le\tilde f$ and $\int_X\psi\,d\mu=c\int_X\varphi\,d\mu$. Taking suprema over such functions gives $\int_X c\tilde f\,d\mu=c\int_X\tilde f\,d\mu$, i.e. $\int_\Omega cf\,d\mu=c\int_\Omega f\,d\mu$.

\end{proof}

