\begin{proposition}
\label{prop:8.3.5}
Let $(X,\mathcal{A},\mu)$ be a measure space, let $\Omega\in\mathcal{A}$, and let $f,g:\Omega\to[0,\infty]$ be $\mathcal{A}$-measurable. Define the integral over $\Omega$ by $\int_\Omega f\,d\mu:=\int_X f\chi_\Omega\,d\mu$.
 If $\Omega' \subseteq \Omega$ is measurable, then $\int_{\Omega'} f\,d\mu = \int_{\Omega} f\chi_{\Omega'}\,d\mu \leq \int_{\Omega} f\,d\mu$.

\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.3.5}
Extend $f$ and $g$ to $X$ by $\tilde f:=f\chi_\Omega$ and $\tilde g:=g\chi_\Omega$. Then $\tilde f,\tilde g:X\to[0,\infty]$ are measurable and $\int_\Omega f\,d\mu=\int_X \tilde f\,d\mu$, $\int_\Omega g\,d\mu=\int_X \tilde g\,d\mu$.

 If $\Omega'\subseteq\Omega$ is measurable, then $f\chi_{\Omega'}$ on $\Omega$ extends to $X$ as $\tilde f\chi_{\Omega'}=f\chi_{\Omega'}$. By the definition of the integral over a measurable subset,
\[
\label{eq:8.u36}
\int_{\Omega'} f\,d\mu = \int_X f\chi_{\Omega'}\,d\mu = \int_X \tilde f\chi_{\Omega'}\,d\mu = \int_{\Omega} f\chi_{\Omega'}\,d\mu.
\]
Since $0\le \tilde f\chi_{\Omega'}\le \tilde f$, part (c) yields $\int_{\Omega'} f\,d\mu\le \int_{\Omega} f\,d\mu$.
\end{proof}

