\begin{theorem}
\label{thm:8.1}
(Lebesgue monotone convergence theorem) Let $\Omega\subseteq\mathbb{R}^n$ be measurable, and let $(f_n)_{n=1}^\infty$ be a sequence of measurable functions $f_n:\Omega\to[0,+\infty]$ such that
\[
\label{eq:8.u37}
0\le f_1(x)\le f_2(x)\le \cdots\quad\text{for all }x\in\Omega.
\]
Define $f:=\sup_{n\ge1} f_n$ (pointwise). Then
\[
\label{eq:8.u38}
0\le \int_{\Omega} f_1\le \int_{\Omega} f_2\le \cdots
\]
and
\[
\label{eq:8.u39}
\int_{\Omega} f\,=\,\sup_{n\ge1}\int_{\Omega} f_n.
\]
\end{theorem}

\begin{lemma}
\label{lem:8.5}
[Interchange of addition and integration]
Let $\Omega\subseteq\mathbb{R}^n$ be measurable, and let $f,g:\Omega\to[0,\infty]$ be measurable. Then
\[
\label{eq:8.u50}
\int_{\Omega} (f+g)\,=\,\int_{\Omega} f+\int_{\Omega} g.
\]
\end{lemma}

\begin{theorem}
\label{thm:8.2}
Let $\Omega$ be a measurable subset of $\mathbb{R}^n$. Let $(g_n)_{n\ge 1}$ be a sequence of measurable functions $g_n:\Omega\to[0,\infty]$. Define the pointwise series
\[
\label{eq:8.u56}
G(x):=\sum_{n=1}^{\infty} g_n(x)\in[0,\infty]\quad (x\in\Omega).
\]
Then $G$ is measurable and
\[
\label{eq:8.u57}
\int_{\Omega} G\,=\,\sum_{n=1}^{\infty} \int_{\Omega} g_n,
\]
where both sides are understood as extended real numbers in $[0,\infty]$.
\end{theorem}

\begin{lemma}
\label{lem:8.6}
[Fatou's lemma]
Let $\Omega\subset\mathbb{R}^n$ be measurable, and let $(f_n)_{n\ge 1}$ be a sequence of measurable functions $f_n:\Omega\to[0,\infty]$. Then
\[
\label{eq:8.u63}
\int_{\Omega} \liminf_{n\to\infty} f_n\,dx \le \liminf_{n\to\infty} \int_{\Omega} f_n\,dx.
\]
\end{lemma}

\begin{proposition}
\label{prop:8.4}
Let $(\Omega,\mathcal{F},\mu)$ be a measure space and let $f: \Omega \to [0,+\infty]$ be a measurable function. If
\[
\label{eq:8.u70}
\int_{\Omega} f\,d\mu < +\infty,
\]
then $f(\omega)<+\infty$ for $\mu$-almost every $\omega\in\Omega$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.4}
Set $A:=\{\omega\in\Omega: f(\omega)=+\infty\}$. Then $A\in\mathcal{F}$ because $f$ is measurable and $A=\bigcap_{n\in\mathbb{N}}\{f\ge n\}$. For each $n\in\mathbb{N}$, one has $f\ge n\mathbf{1}_A$, hence
\[
\label{eq:8.u71}
\int_{\Omega} f\,d\mu \ge \int_{\Omega} n\mathbf{1}_A\,d\mu = n\,\mu(A).
\]
If $\mu(A)>0$, then the right-hand side tends to $+\infty$ as $n\to\infty$, forcing $\int_{\Omega} f\,d\mu=+\infty$, a contradiction. Therefore $\mu(A)=0$, which means $f<+\infty$ $\mu$-almost everywhere.
\end{proof}

