\begin{lemma}
\label{lem:8.7}
Let $\Omega\subset\mathbb{R}^n$ be measurable, and let $f:\Omega\to[0,\infty]$ be measurable. If $\int_{\Omega} f\,dx<\infty$, then $f(x)<\infty$ for almost every $x\in\Omega$, i.e. $|\{x\in\Omega: f(x)=+\infty\}|=0$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:8.7}
Set $E:=\{x\in\Omega: f(x)=+\infty\}$, which is measurable since $f$ is measurable. For each $m\in\mathbb{N}$, one has $f\ge m\,\mathbf{1}_E$ pointwise on $\Omega$. By monotonicity of the Lebesgue integral,
\[
\label{eq:8.u72}
\int_{\Omega} f\,dx\ge \int_{\Omega} m\,\mathbf{1}_E\,dx = m\,|E|.
\]
Since $\int_{\Omega} f\,dx<\infty$, it follows that $m\,|E|<\infty$ for all $m$, hence $|E|\le \frac{1}{m}\int_{\Omega} f\,dx$ for all $m$. Letting $m\to\infty$ yields $|E|=0$, so $f(x)<\infty$ for almost every $x\in\Omega$.
\end{proof}

