\begin{lemma}
\label{lem:8.8}
[Borel--Cantelli]
Let $(\mathbb{R}^n,\mathcal{L}^n,m)$ be Lebesgue measure space, and let $\Omega_1,\Omega_2,\ldots$ be measurable subsets of $\mathbb{R}^n$ such that
\[
\label{eq:8.u73}
\sum_{k=1}^\infty m(\Omega_k)<\infty.
\]
Define
\[
\label{eq:8.u74}
\limsup_{k\to\infty} \Omega_k:=\bigcap_{N=1}^\infty \bigcup_{k\ge N} \Omega_k
\]
(the set of points that belong to $\Omega_k$ for infinitely many $k$). Then
\[
\label{eq:8.u75}
m\bigl(\limsup_{k\to\infty}\Omega_k\bigr)=0.
\]
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:8.8}
For each $N\ge 1$ set $E_N:=\bigcup_{k\ge N}\Omega_k$. Then $E_{N+1}\subseteq E_N$ and
\[
\label{eq:8.u76}
\limsup_{k\to\infty}\Omega_k=\bigcap_{N=1}^\infty E_N.
\]
By countable subadditivity,
\[
\label{eq:8.u77}
m(E_N)=m\Bigl(\bigcup_{k\ge N}\Omega_k\Bigr)\le \sum_{k\ge N} m(\Omega_k).
\]
Since $\sum_{k=1}^\infty m(\Omega_k)<\infty$, the tail sums satisfy $\sum_{k\ge N} m(\Omega_k)\to 0$ as $N\to\infty$, hence $m(E_N)\to 0$.

Because $(E_N)$ is a decreasing sequence of measurable sets with $m(E_1)\le \sum_{k\ge 1} m(\Omega_k)<\infty$, continuity from above gives
\[
\label{eq:8.u78}
m\Bigl(\bigcap_{N=1}^\infty E_N\Bigr)=\lim_{N\to\infty} m(E_N)=0.
\]
Therefore $m(\limsup_{k\to\infty}\Omega_k)=0$.
\end{proof}

