\begin{proposition}
\label{prop:8.5}
Let $\Omega\subset\mathbb{R}^n$ be measurable, and let $f,g:\Omega\to[0,+\infty]$ be measurable. Then
\[
\label{eq:8.u79}
\int_{\Omega}(f+g)\,\ge\,\int_{\Omega}f\,+\,\int_{\Omega}g.
\]
\end{proposition}

\begin{proposition}
\label{prop:8.6}
Let $p>2$ and $c>0$. Define
\[
\label{eq:8.u83}
E:=\left\{ x \in [0,1] : \left|x-\frac{a}{q}\right|\le \frac{c}{q^p}\text{ for infinitely many pairs of positive integers }(a,q)\right\}.
\]
Then $E$ has Lebesgue measure zero.
\end{proposition}

\begin{definition}
\label{def:8.7}
A real number \(x\in\mathbb{R}\) is called \emph{diophantine} if there exist real numbers \(p>0\) and \(C>0\) such that
\[
\label{eq:8.u89}
\left|x-\frac{a}{q}\right|>\frac{C}{|q|^p}
\]
for all nonzero integers \(q\) and all integers \(a\).
\end{definition}

\begin{theorem}
\label{thm:8.3}
Let $\tau>2$. A real number $x\in\mathbb{R}$ is called \emph{diophantine of exponent $\tau$} if there exists $c(x)>0$ such that
\[
\label{eq:8.u90}
\left|x-\frac{p}{q}\right|\ge \frac{c(x)}{q^{\tau}}\qquad\text{for all }p\in\mathbb{Z},\ q\in\mathbb{N}.
\]
Then the set of real numbers that are diophantine of exponent $\tau$ has full Lebesgue measure in $\mathbb{R}$. Equivalently, for Lebesgue-almost every $x\in\mathbb{R}$ there exists $c(x)>0$ such that
\[
\label{eq:8.u91}
\left|x-\frac{p}{q}\right|\ge \frac{c(x)}{q^{\tau}}\qquad\text{for all }p\in\mathbb{Z},\ q\in\mathbb{N}.
\]
\end{theorem}

\begin{proposition}
\label{prop:8.7}
Let $(f_n)_{n\ge 1}$ be Lebesgue measurable functions $f_n:\mathbb{R}\to[0,\infty)$ such that
\[
\label{eq:8.u101}
\int_{\mathbb{R}} f_n\,dm\le \frac{1}{4^n}\qquad(n\ge 1).
\]
Then for every $\varepsilon>0$ there exists a Lebesgue measurable set $E\subset\mathbb{R}$ with $m(E)\le \varepsilon$ such that $\lim_{n\to\infty} f_n(x)=0$ for all $x\in\mathbb{R}\setminus E$.
\end{proposition}

\begin{theorem}
\label{thm:8.4}
[Egoroff on $[0,1]$]
Let $(f_n)_{n\ge 1}$ be measurable functions $f_n:[0,1]\to[0,\infty)$ such that $f_n(x)\to 0$ for every $x\in[0,1]$. Then for every $\varepsilon>0$ there exists a measurable set $E\subset[0,1]$ with $m(E)\le \varepsilon$ such that $f_n\to 0$ uniformly on $[0,1]\setminus E$.
\end{theorem}

\begin{proposition}
\label{prop:8.8}
There exists a bounded function $f:\mathbb{N}\times\mathbb{N}\to\mathbb{R}^+$ such that:
\begin{enumerate}
\item for every $n\in\mathbb{N}$, the series $\sum_{m=1}^{\infty} f(n,m)$ converges;
\item for every $m\in\mathbb{N}$, the limit $\lim_{n\to\infty} f(n,m)$ exists;
\item nevertheless,
\[
\label{eq:8.u112}
\lim_{n \to \infty} \sum_{m=1}^{\infty} f(n, m) \neq \sum_{m=1}^{\infty} \lim_{n \to \infty} f(n, m).
\]
\end{enumerate}
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.8}
Define $f:\mathbb{N}\times\mathbb{N}\to\mathbb{R}^+$ by
\[
\label{eq:8.u113}
f(n,m)=\begin{cases}
1,& m\le n,\\
0,& m>n.
\end{cases}
\]
Then $0\le f(n,m)\le 1$ for all $(n,m)$, so $f$ is bounded and $f(n,m)\in\mathbb{R}^+$.

(1) Fix $n\in\mathbb{N}$. Then $f(n,m)=0$ for all $m>n$, so
\[
\label{eq:8.u114}
\sum_{m=1}^{\infty} f(n,m)=\sum_{m=1}^{n} 1 = n,
\]
hence the series converges (indeed it is finite).

(2) Fix $m\in\mathbb{N}$. For all $n\ge m$, one has $m\le n$ and hence $f(n,m)=1$. Therefore $\lim_{n\to\infty} f(n,m)=1$.

(3) For each $n$, the computation in (1) gives $\sum_{m=1}^{\infty} f(n,m)=n$, so
\[
\label{eq:8.u115}
\lim_{n\to\infty}\sum_{m=1}^{\infty} f(n,m)=\lim_{n\to\infty} n = +\infty.
\]
On the other hand, by (2) one has $\lim_{n\to\infty} f(n,m)=1$ for every $m$, hence
\[
\label{eq:8.u116}
\sum_{m=1}^{\infty} \lim_{n\to\infty} f(n,m)=\sum_{m=1}^{\infty} 1 = +\infty.
\]
Thus the right-hand side is not a convergent real series, while the left-hand side is the extended real number $+\infty$; in particular, the equality of real numbers fails, and the interchange of limit and infinite sum is not valid under the stated hypotheses.
\end{proof}

