\begin{definition}
\label{def:8.8}
Let $\Omega\subseteq\mathbb{R}^n$ be a measurable set. A measurable function $f:\Omega\to\mathbb{R}^*$ is called \emph{absolutely integrable on $\Omega$} if
\[
\label{eq:8.u117}
\int_{\Omega} |f(x)|\,dx<\infty,
\]
where the integral is the (Lebesgue) integral over $\Omega$.
\end{definition}

\begin{definition}
\label{def:8.9}
Let $f$ be a real-valued function. Define the positive and negative parts of $f$ by
\[
\label{eq:8.u118}
f^+ := \max(f,0),\qquad f^- := -\min(f,0).
\]
\end{definition}

\begin{proposition}
\label{prop:8.9}
Let $f$ be a real-valued function and define $f^+$ and $f^-$ by
\[
\label{eq:8.u119}
f^+ := \max(f,0),\qquad f^- := -\min(f,0).
\]
Then $f^+\ge 0$ and $f^-\ge 0$, and
\[
\label{eq:8.u120}
f = f^+ - f^-,\qquad |f| = f^+ + f^-.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.9}
For each $x$,   if $f(x)\ge 0$ then $f^+(x)=f(x)$ and $f^-(x)=0$;\
  if $f(x)<0$ then $f^+(x)=0$ and $f^-(x)=-f(x)$. \
In either case $f^+(x),f^-(x)\ge 0$ and $f(x)=f^+(x)-f^-(x)$. \
Moreover, if $f(x)\ge 0$ then $|f(x)|=f(x)=f^+(x)+f^-(x)$, \
and if $f(x)<0$ then $|f(x)|=-f(x)=f^+(x)+f^-(x)$.
\end{proof}

