\begin{definition}
\label{def:8.10}
[Lebesgue integral]
Let $(\Omega,\mathcal F,\mu)$ be a measure space and let $f: \Omega\to\overline{\mathbb R}$ be a measurable function such that
\[
\label{eq:8.u121}
\int_{\Omega} |f|\,d\mu<\infty.
\]
Define the positive and negative parts of $f$ by
\[
\label{eq:8.u122}
f^{+}:=\max\{f,0\},\qquad f^{-}:=\max\{-f,0\}.
\]
The (Lebesgue) integral of $f$ over $\Omega$ is defined by
\[
\label{eq:8.u123}
\int_{\Omega} f\,d\mu:=\int_{\Omega} f^{+}\,d\mu-\int_{\Omega} f^{-}\,d\mu.
\]
\end{definition}

\begin{proposition}
\label{prop:8.10.1}
Let $(\Omega,\mathcal{A},\mu)$ be a measure space. Let $f,g:\Omega\to\mathbb{R}$ be absolutely integrable, i.e. $\int_{\Omega} |f|\,d\mu<\infty$ and $\int_{\Omega} |g|\,d\mu<\infty$. For every $c\in\mathbb{R}$, the function $cf$ is absolutely integrable and
\[
\label{eq:8.u124}
\int_{\Omega} cf\,d\mu = c\int_{\Omega} f\,d\mu.
\]

\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.10.1}
Since $|cf|=|c|\,|f|$, one has $\int_{\Omega}|cf|\,d\mu=|c|\int_{\Omega}|f|\,d\mu<\infty$, so $cf$ is absolutely integrable. If $c\ge 0$, linearity of the integral gives $\int_{\Omega} cf\,d\mu=c\int_{\Omega} f\,d\mu$. If $c<0$, then $\int_{\Omega} cf\,d\mu=\int_{\Omega} (|c|(-f))\,d\mu=|c|\int_{\Omega} (-f)\,d\mu=c\int_{\Omega} f\,d\mu$.


\end{proof}

