\begin{proposition}
\label{prop:8.10.2}
Let $(\Omega,\mathcal{A},\mu)$ be a measure space. Let $f,g:\Omega\to\mathbb{R}$ be absolutely integrable, i.e. $\int_{\Omega} |f|\,d\mu<\infty$ and $\int_{\Omega} |g|\,d\mu<\infty$. The function $f+g$ is absolutely integrable and
\[
\label{eq:8.u125}
\int_{\Omega} (f+g)\,d\mu = \int_{\Omega} f\,d\mu + \int_{\Omega} g\,d\mu.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.10.2}
By the triangle inequality, $|f+g|\le |f|+|g|$, hence
\[
\label{eq:8.u128}
\int_{\Omega}|f+g|\,d\mu\le \int_{\Omega}|f|\,d\mu+\int_{\Omega}|g|\,d\mu<\infty,
\]
so $f+g$ is absolutely integrable. Linearity of the integral yields $\int_{\Omega}(f+g)\,d\mu=\int_{\Omega}f\,d\mu+\int_{\Omega}g\,d\mu$.
\end{proof}

