\begin{proposition}
\label{prop:8.10.3}
Let $(\Omega,\mathcal{A},\mu)$ be a measure space. Let $f,g:\Omega\to\mathbb{R}$ be absolutely integrable, i.e. $\int_{\Omega} |f|\,d\mu<\infty$ and $\int_{\Omega} |g|\,d\mu<\infty$. If $f(x)\le g(x)$ for all $x\in\Omega$, then
\[
\label{eq:8.u126}
\int_{\Omega} f\,d\mu\le \int_{\Omega} g\,d\mu.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.10.3}
If $f\le g$, then $g-f\ge 0$. Since $\int_{\Omega}|g-f|\,d\mu\le \int_{\Omega}(|g|+|f|)\,d\mu<\infty$, the function $g-f$ is integrable and nonnegative, hence $\int_{\Omega}(g-f)\,d\mu\ge 0$. By linearity,
\[
\label{eq:8.u129}
0\le \int_{\Omega}(g-f)\,d\mu=\int_{\Omega}g\,d\mu-\int_{\Omega}f\,d\mu,
\]
which is equivalent to $\int_{\Omega} f\,d\mu\le \int_{\Omega} g\,d\mu$.
\end{proof}

