\begin{proposition}
\label{prop:8.10.4}
Let $(\Omega,\mathcal{A},\mu)$ be a measure space. Let $f,g:\Omega\to\mathbb{R}$ be absolutely integrable, i.e. $\int_{\Omega} |f|\,d\mu<\infty$ and $\int_{\Omega} |g|\,d\mu<\infty$.  If $f(x)=g(x)$ for $\mu$-almost every $x\in\Omega$, then
\[
\label{eq:8.u127}
\int_{\Omega} f\,d\mu = \int_{\Omega} g\,d\mu.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.10.4}
 If $f=g$ $\mu$-a.e., then $h:=f-g$ satisfies $h=0$ $\mu$-a.e. and $|h|\le |f|+|g|$, so $h$ is integrable. For each $n\in\mathbb{N}$ define $A_n:=\{x\in\Omega: |h(x)|\ge 1/n\}$. Then $A_n\subseteq\{h\ne 0\}$, so $\mu(A_n)=0$, and
\[
\label{eq:8.u130}
\int_{\Omega}|h|\,d\mu=\int_{A_n}|h|\,d\mu+\int_{\Omega\setminus A_n}|h|\,d\mu\le 0+\frac{1}{n}\mu(\Omega).
\]
If $\mu(\Omega)<\infty$, letting $n\to\infty$ gives $\int_{\Omega}|h|\,d\mu=0$, hence $\int_{\Omega}h\,d\mu=0$ and therefore $\int_{\Omega}f\,d\mu=\int_{\Omega}g\,d\mu$.
\end{proof}

