\begin{theorem}
\label{thm:8.5}
[Lebesgue dominated convergence theorem]
Let $\Omega\subseteq\mathbb{R}^n$ be measurable. Let $(f_n)_{n\ge 1}$ be a sequence of measurable functions $f_n:\Omega\to\mathbb{R}^*$ such that $f_n(x)\to f(x)$ for every $x\in\Omega$, where $f:\Omega\to\mathbb{R}^*$ is the pointwise limit. Assume there exists a measurable function $F:\Omega\to[0,\infty]$ with $\int_\Omega F<\infty$ and such that
\[
\label{eq:8.u131}
|f_n(x)|\le F(x)\quad\text{for all }x\in\Omega\text{ and all }n\ge 1.
\]
Then $f$ is measurable, $\int_\Omega |f|<\infty$, and
\[
\label{eq:8.u132}
\int_{\Omega} f = \lim_{n\to\infty}\int_{\Omega} f_n.
\]
\end{theorem}

\begin{definition}
\label{def:8.11}
[Upper and lower Lebesgue integrals]
Let $\Omega\subset\mathbb{R}^n$ be Lebesgue measurable and let $f:\Omega\to\mathbb{R}$ be an arbitrary function. The \emph{upper Lebesgue integral} of $f$ over $\Omega$ is defined by
\[
\label{eq:8.u135}
\overline{\int_{\Omega}} f\, :=\, \inf\Bigl\{\int_{\Omega} g\; :\; g\text{ is absolutely integrable on }\Omega\text{ and }g(x)\ge f(x)\text{ for all }x\in\Omega\Bigr\}.
\]
The \emph{lower Lebesgue integral} of $f$ over $\Omega$ is defined by
\[
\label{eq:8.u136}
\underline{\int_{\Omega}} f\, :=\, \sup\Bigl\{\int_{\Omega} g\; :\; g\text{ is absolutely integrable on }\Omega\text{ and }g(x)\le f(x)\text{ for all }x\in\Omega\Bigr\}.
\]
\end{definition}

\begin{lemma}
\label{lem:8.9}
Let $\Omega\subset\mathbb{R}^n$ be measurable, and let $f:\Omega\to\mathbb{R}$ be a function (not assumed measurable). Suppose there exists $A\in\mathbb{R}$ such that the upper and lower integrals of $f$ over $\Omega$ are finite and equal:
\[
\label{eq:8.u137}
\overline{\int}_{\Omega} f=\underline{\int}_{\Omega} f=A.
\]
Then $f$ is integrable over $\Omega$ (in the sense that $\overline{\int}_{\Omega} f=\underline{\int}_{\Omega} f$), $f$ is absolutely integrable (i.e. $\int_{\Omega} |f|<\infty$), and
\[
\label{eq:8.u138}
\int_{\Omega} f=\overline{\int}_{\Omega} f=\underline{\int}_{\Omega} f=A,
\qquad
\overline{\int}_{\Omega}(-f)=\underline{\int}_{\Omega}(-f)=-A.
\]
In particular,
\[
\label{eq:8.u139}
\int_{\Omega} f = \overline{\int}_{\Omega} f = \int_{-\Omega} f = A.
\]
\end{lemma}

\begin{proposition}
\label{prop:8.11}
Let $f,g:\mathbb{R}\to\mathbb{R}$ be measurable functions such that $f,g\in L^{1}(\mathbb{R})$. Assume that $f(x)\le g(x)$ for all $x\in\mathbb{R}$ and that
\[
\label{eq:8.u146}
\int_{\mathbb{R}} f(x)\,dx=\int_{\mathbb{R}} g(x)\,dx.
\]
Then $f(x)=g(x)$ for almost every $x\in\mathbb{R}$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.11}
Define $h=g-f$. Then $h$ is measurable, $h\ge 0$ pointwise, and $h\in L^{1}(\mathbb{R})$. Moreover,
\[
\label{eq:8.u147}
\int_{\mathbb{R}} h(x)\,dx=\int_{\mathbb{R}} g(x)\,dx-\int_{\mathbb{R}} f(x)\,dx=0.
\]
Let $A=\{x\in\mathbb{R}: h(x)>0\}$. For each $n\in\mathbb{N}$ set $A_n=\{x\in\mathbb{R}: h(x)\ge 1/n\}$. Then $A=\bigcup_{n=1}^\infty A_n$. If $m(A_n)>0$ for some $n$, then
\[
\label{eq:8.u148}
\int_{\mathbb{R}} h(x)\,dx\ge \int_{A_n} h(x)\,dx\ge \frac{1}{n}m(A_n)>0,
\]
contradicting $\int_{\mathbb{R}} h=0$. Hence $m(A_n)=0$ for all $n$, so $m(A)=0$. Therefore $h(x)=0$ for almost every $x$, i.e. $f(x)=g(x)$ for almost every $x$.
\end{proof}

