\begin{proposition}
\label{prop:8.12}
For each $n\in\mathbb{N}$, define $f_n:\mathbb{R}\to\mathbb{R}$ by
\[
\label{eq:8.u149}
f_n=\chi_{[n,n+1)}-\chi_{[n+1,n+2)}.
\]
Then the series $\sum_{n=1}^\infty f_n(x)$ converges pointwise for every $x\in\mathbb{R}$ to the function $g:=\chi_{[1,2)}$, and
\[
\label{eq:8.u150}
\int_{\mathbb{R}} \sum_{n=1}^{\infty} f_n\,dm \ne \sum_{n=1}^{\infty} \int_{\mathbb{R}} f_n\,dm,
\]
where $m$ denotes Lebesgue measure on $\mathbb{R}$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:8.12}
Fix $x\in\mathbb{R}$. If $x<1$, then $f_n(x)=0$ for all $n\ge 1$, so $\sum_{n=1}^\infty f_n(x)=0$. If $x\in[1,2)$, then $f_1(x)=1$ and $f_n(x)=0$ for all $n\ge 2$, hence $\sum_{n=1}^\infty f_n(x)=1$. If $x\ge 2$, then there exists a unique integer $k\ge 2$ such that $x\in[k,k+1)$. In that case, $f_k(x)=1$, $f_{k-1}(x)=-1$, and $f_n(x)=0$ for all $n\notin\{k-1,k\}$, so $\sum_{n=1}^\infty f_n(x)=0$. Therefore the pointwise sum is $g(x)=\chi_{[1,2)}(x)$.

Consequently,
\[
\label{eq:8.u151}
\int_{\mathbb{R}} \sum_{n=1}^{\infty} f_n\,dm=\int_{\mathbb{R}} g\,dm=m([1,2))=1.
\]
On the other hand, for each $n\in\mathbb{N}$,
\[
\label{eq:8.u152}
\int_{\mathbb{R}} f_n\,dm=\int_{\mathbb{R}} \chi_{[n,n+1)}\,dm-\int_{\mathbb{R}} \chi_{[n+1,n+2)}\,dm=m([n,n+1))-m([n+1,n+2))=1-1=0.
\]
Hence $\sum_{n=1}^\infty \int_{\mathbb{R}} f_n\,dm=\sum_{n=1}^\infty 0=0$, which differs from $1$. This proves the inequality.
\end{proof}

