\begin{proposition}
\label{prop:8.14}
Define $f:[0,1]\to\mathbb{R}$ by
\[
\label{eq:8.u160}
f(x)=\begin{cases}
1, & x\in\mathbb{Q},\\
0, & x\notin\mathbb{Q}.
