\begin{theorem}
\label{thm:8.7}
[Fubini's theorem]
Let $f:\mathbb{R}^2\to\mathbb{R}$ be Lebesgue measurable and satisfy
\[
\label{eq:8.u173}
\int_{\mathbb{R}^2} |f(x,y)|\,dx\,dy<\infty.
\]
Then the following hold.
\begin{enumerate}
\item For almost every $x\in\mathbb{R}$, the function $y\mapsto f(x,y)$ is absolutely integrable on $\mathbb{R}$, and the function
\[
\label{eq:8.u174}
F(x):=\int_{\mathbb{R}} f(x,y)\,dy
\]
is defined for almost every $x$ and belongs to $L^1(\mathbb{R})$.
\item For almost every $y\in\mathbb{R}$, the function $x\mapsto f(x,y)$ is absolutely integrable on $\mathbb{R}$, and the function
\[
\label{eq:8.u175}
G(y):=\int_{\mathbb{R}} f(x,y)\,dx
\]
is defined for almost every $y$ and belongs to $L^1(\mathbb{R})$.
\item The iterated integrals agree with the integral over $\mathbb{R}^2$:
\[
\label{eq:8.u176}
\int_{\mathbb{R}} F(x)\,dx \,=\, \int_{\mathbb{R}^2} f(x,y)\,dx\,dy \,=\, \int_{\mathbb{R}} G(y)\,dy.
\]
\end{enumerate}
\end{theorem}
